export function transformMapScript(source, target, map, log, isUpdate) {
    // Transform map script with module support
    log.info('Processing import set transform with module')

    // Set default values for new records
    if (!isUpdate) {
        target.setValue('active', 'true')
        target.setValue('state', '1')
    }

    // Log the transformation
    const name = source.getValue('name')
    log.info(`Transforming record: ${name}`)
}
